{{
  (() => {
    // 1. On identifie l'onglet actif
    const ongletActif = Tabs1.selectedTab || "🛠️ Atelier Global";

    // 2. On choisit la BONNE source de données selon l'onglet
    // Si l'onglet contient "Global", on prend les données Globales, sinon on prend les données Perso
    const data = ongletActif.includes("Global") 
      ? (Get_Atelier_Global.data || []) 
      : (Get_Atelier_Perso.data || []);

    // 3. On formate le nom pour l'affichage (majuscules)
    const nomAffichage = ongletActif.toUpperCase();

    if (!data.length) return ` ${nomAffichage} (0)`;

    // 4. Initialisation des compteurs
    let count2T = 0;
    let count4T = 0;
    let countRobot = 0;
    let totalActifs = 0;

    // 5. Boucle sur les données pour compter
    for (let i = 0; i < data.length; i++) {
      const row = data[i];

      if (row.isHeader) continue;

      const st = (row.Statut || "").toUpperCase().trim();

      if (st.includes("PRÊT") || st.includes("PRET") || st.includes("H.S") || st.includes("FACTUR")) {
        continue;
      }

      totalActifs++;

      const cat = (row.Categorie_Materiel || "").toUpperCase().trim();

      if (cat.includes("2T")) count2T++;
      else if (cat.includes("4T")) count4T++;
      else if (cat.includes("ROBOT")) countRobot++;
    }

    // 6. Affichage final
    return ` ${nomAffichage} (${totalActifs}) : 2T (${count2T}) - 4T (${count4T}) - Robot (${countRobot})`;
  })()
}}
